CREATE FUNCTION public.planning_external_invite_replacement_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.invite_hash IS DISTINCT FROM OLD.invite_hash AND NEW.invite_hash IS NOT NULL AND OLD.deleted_at IS NULL AND (OLD.status='active' OR (OLD.status IN ('pending','sent') AND OLD.invite_expires_at>now())) THEN RAISE EXCEPTION 'Deltakeren har allerede en aktiv tilgang eller invitasjon. Avslutt tilgangen før ny invitasjon.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER planning_external_invite_replacement_guard BEFORE UPDATE OF invite_hash ON public.planning_external_participants FOR EACH ROW EXECUTE FUNCTION public.planning_external_invite_replacement_guard();
CREATE OR REPLACE FUNCTION public.planning_external_channel(_token text,_project_id uuid,_channel text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; BEGIN
 e:=public.planning_external_identity(_token);
 IF e.id IS NULL OR _project_id IS NULL OR e.planning_project_id IS DISTINCT FROM _project_id OR public.planning_channel_matches(e.participant_type,_channel) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang til samtalen' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('audience',public.planning_channel_people(_project_id,_channel),'messages',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'body',m.body,'author_name',m.author_name,'created_at',m.created_at,'reply_to_id',m.reply_to_id,'recipient_snapshot',m.recipient_snapshot) ORDER BY m.created_at) FROM public.planning_messages m WHERE m.planning_project_id=_project_id AND m.channel=_channel AND m.deleted_at IS NULL AND (m.external_author_id=e.id OR m.recipient_snapshot @> jsonb_build_array(jsonb_build_object('id',e.id,'kind','external')))),'[]'::jsonb)); END $$;
COMMENT ON FUNCTION public.planning_external_invite_replacement_guard() IS 'Do not rotate a live invite/session during concurrent delivery. Revoke explicitly before reinviting.';